/**
 * Designstager - DS AI Studio - Auto-load Draft from My Creations Hub
 * Run: Everywhere
 *
 * Net-additive, standalone snippet. When a page is loaded with a
 * "?ds_load_ppt=DRAFT_ID" query param (as generated by the "Open" button
 * on the My Creations Hub Presentations tab), this waits for the AI
 * Studio page's existing window.dspLoadDraft() function to become
 * available and then calls it, so the draft opens in the editor.
 * The AI Studio page is very heavy on initial load and its /load-ppt
 * call can intermittently 503 under that contention, so this retries
 * a few times with backoff before giving up. Does nothing on any
 * page/request without the query param.
 */
add_action('wp_footer', function() {
    if (empty($_GET['ds_load_ppt'])) return;
    $draft_id = sanitize_text_field(wp_unslash($_GET['ds_load_ppt']));
    ?>
    <script>
    (function(){
        var DS_LOAD_ID = <?php echo wp_json_encode($draft_id); ?>;
        var tries = 0;
        var attempts = 0;
        var maxAttempts = 4;

        function attemptLoad(){
            attempts++;
            if (typeof window.dspLoadDraft === 'function') {
                window.dspLoadDraft(DS_LOAD_ID);
                if (attempts < maxAttempts) {
                    setTimeout(function(){
                        if (!window.G || window.G.pptId !== DS_LOAD_ID) {
                            attemptLoad();
                        }
                    }, 2500 * attempts);
                }
            }
        }

        var iv = setInterval(function(){
            tries++;
            if (typeof window.dspLoadDraft === 'function') {
                clearInterval(iv);
                setTimeout(attemptLoad, 1200);
            } else if (tries > 150) {
                clearInterval(iv);
            }
        }, 100);
    })();
    </script>
    <?php
}, 999);
